public class SavingsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Savings s = new Savings();
        s.deposit(200.0);
        check("inherited deposit", 200.0, s.getBalance());

        s.addInterest(0.10);
        check("addInterest(0.10) on 200.0", 220.0, s.getBalance());

        Savings fresh = new Savings();
        fresh.deposit(100.0);
        fresh.addInterest(0.25);
        check("addInterest(0.25) on 100.0", 125.0, fresh.getBalance());

        check("Savings monthlyFee", 0.0, s.monthlyFee());
        check("Checking monthlyFee", 12.0, new Checking().monthlyFee());

        Account viaBaseType = new Savings();
        check("dynamic dispatch through Account", 0.0, viaBaseType.monthlyFee());

        Account[] all = { new Savings(), new Checking(), new Checking() };
        check("totalFees of 1 savings + 2 checking", 24.0, Savings.totalFees(all));

        check("totalFees of an empty array", 0.0, Savings.totalFees(new Account[0]));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

